+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+import java.util.UUID;
+import org.springframework.stereotype.Service;
+
+@Service
+public class MessageStore {
+    public record Message(UUID id, String name, String email, String phone, String message) {
+        public Message(String name, String email, String phone, String message) {
+            this(UUID.randomUUID(), name, email, phone, message);
+        }
+    }
+
+    private final List<Message> messages = new ArrayList<>();
+
+    public synchronized void add(Message message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<Message> findAll() {
+        return List.copyOf(messages);
+    }
+}
